describe('Edit Existing Task Functionality', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should successfully edit an existing task by clicking Edit button', () => {
    // Intercept the API call for fetching tasks
    cy.intercept('GET', '/api/tasks').as('getTasks');
    cy.wait('@getTasks');

    // Verify task list is displayed
    cy.get('[data-testid="task-item-1"]').should('be.visible');
    cy.get('[data-testid="task-title-1"]').should('contain', 'Complete project report');

    // Click Edit button for the first task
    cy.get('[data-testid="edit-button-1"]').click();

    // Verify edit modal appears
    cy.get('[data-testid="edit-modal"]').should('be.visible');
    cy.get('[data-testid="task-title-input"]').should('have.value', 'Complete project report');
    cy.get('[data-testid="task-description-textarea"]').should('contain', 'Write a detailed project report');

    // Update task title and description
    cy.get('[data-testid="task-title-input"]').clear().type('Finalize project report');
    cy.get('[data-testid="task-description-textarea"]').clear().type('Review and finalize the project report');

    // Click Save button
    cy.get('[data-testid="save-edit-button"]').click();

    // Verify API call for updating task
    cy.intercept('PUT', '/api/tasks/1').as('updateTask');
    cy.wait('@updateTask');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Task updated successfully');

    // Verify modal closes
    cy.get('[data-testid="edit-modal"]').should('not.exist');

    // Verify task title is updated in the list
    cy.get('[data-testid="task-title-1"]').should('contain', 'Finalize project report');
  });

  it('should handle validation when submitting an empty task title', () => {
    // Intercept the API call for fetching tasks
    cy.intercept('GET', '/api/tasks').as('getTasks');
    cy.wait('@getTasks');

    // Click Edit button for the first task
    cy.get('[data-testid="edit-button-1"]').click();

    // Verify edit modal appears
    cy.get('[data-testid="edit-modal"]').should('be.visible');

    // Clear task title input
    cy.get('[data-testid="task-title-input"]').clear();

    // Attempt to save with empty title
    cy.get('[data-testid="save-edit-button"]').click();

    // Verify validation error message appears
    cy.get('[data-testid="validation-error"]').should('be.visible').should('contain', 'Task title is required');

    // Verify task was not updated
    cy.get('[data-testid="task-title-input"]').should('have.value', '');

    // Verify modal is still open
    cy.get('[data-testid="edit-modal"]').should('be.visible');

    // Verify no update API call was made
    cy.get('@updateTask', { timeout: 100 }).should('not.exist');
  });
});
